def min_edits(a: str, b: str) -> int:
    prev = list(range(len(b) + 1))       # row for a[:0]: building b[:j] takes j inserts
    for i, ca in enumerate(a, 1):
        cur = [i]                        # emptying a[:i] takes i deletes
        for j, cb in enumerate(b, 1):
            if ca == cb:
                cur.append(prev[j - 1])  # last characters match: nothing to pay
            else:                        # delete ca, insert cb, or replace ca with cb
                cur.append(1 + min(prev[j], cur[j - 1], prev[j - 1]))
        prev = cur
    return prev[-1]
